#ifndef LRU_CACHE_H
#define LRU_CACHE_H

#include <cstddef>
#include <deque>
#include <unordered_map>
#include <optional>
#include <mutex>

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {}

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::optional<V>();
        }
        // Move existing key to front (most recently used)
        list_.splice(list_.begin(), list_, it->second);
        return std::optional<V>(it->second->second);
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            // Update existing key and count as use
            it->second->second = value;
            list_.splice(list_.begin(), list_, it->second);
        } else {
            // Insert new key
            if (capacity_ == 0) {
                return; // No capacity, do nothing
            }
            if (map_.size() >= capacity_) {
                // Evict least recently used (back of list)
                std::size_t evictKey = list_.back().first;
                map_.erase(evictKey);
                list_.pop_back();
            }
            list_.emplace_front(key, value);
            map_.emplace(key, list_.begin());
        }
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return map_.size();
    }

private:
    std::size_t capacity_;
    mutable std::mutex mutex_;
    std::deque<std::pair<K, V>> list_;
    std::unordered_map<K, typename std::deque<std::pair<K, V>>::iterator> map_;
};

#endif // LRU_CACHE_H
