import heapq

def topo_sort(graph):
    # Collect all nodes (both keys and any prerequisite-only nodes)
    all_nodes = set(graph.keys())
    for node, prereqs in graph.items():
        for p in prereqs:
            all_nodes.add(p)

    # Compute in-degree for each node based on dependencies
    # in_degree[node] = number of prerequisites of node that are not yet processed
    in_degree = {node: 0 for node in all_nodes}
    adj = {node: [] for node in all_nodes}  # prereq -> list of dependents

    for node, prereqs in graph.items():
        for p in prereqs:
            adj[p].append(node)
            in_degree[node] += 1

    # Min-heap of ready nodes (in_degree == 0)
    ready = [n for n in all_nodes if in_degree[n] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        curr = heapq.heappop(ready)
        result.append(curr)
        for dep in adj[curr]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(ready, dep)

    if len(result) != len(all_nodes):
        raise ValueError("cycle detected")

    return result
