import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.time.LocalDate;

public class Library {

    public class Book {
        public final String isbn;
        public final String title;
        public String borrower;
        public LocalDate borrowDate;

        public Book(String isbn, String title) {
            this.isbn = isbn;
            this.title = title;
            this.borrower = null;
            this.borrowDate = null;
        }

        public boolean isBorrowed() {
            return this.borrower != null;
        }
    }

    private final Map<String, Book> books = new HashMap<String, Book>();

    public void addBook(String isbn, String title) {
        if (isbn == null) {
            throw new IllegalArgumentException("isbn must not be null");
        }
        if (this.books.containsKey(isbn)) {
            throw new IllegalArgumentException("isbn already exists: " + isbn);
        }
        this.books.set(isbn, new Book(isbn, title));
    }

    public void borrow(String isbn, String member, LocalDate date) {
        Book book = this.books.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("unknown isbn: " + isbn);
        }
        if (book.isBorrowed()) {
            throw new IllegalStateException("book already borrowed: " + isbn);
        }
        book.borrower = member;
        book.borrowDate = date;
    }

    public void giveBack(String isbn) {
        Book book = this.books.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("unknown isbn: " + isbn);
        }
        if (!book.isBorrowed()) {
            throw new IllegalStateException("book not borrowed: " + isbn);
        }
        book.borrower = null;
        book.borrowDate = null;
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<String>();
        for (Book book : this.books.values()) {
            if (book.isBorrowed() && book.borrowDate != null) {
                int duration = today.compareTo(book.borrowDate);
                if (duration > days) {
                    result.add(book.title);
                }
            }
        }
        result.sort();
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> counts = new HashMap<String, Integer>();
        for (Book book : this.books.values()) {
            if (book.isBorrowed()) {
                String member = book.borrower;
                int c = counts.get(member);
                counts.set(member, (c == null ? 0 : c) + 1);
            }
        }
        return counts;
    }
}

public class NoSuchElementException extends Exception {
    public NoSuchElementException(String message) {
        super(message);
    }
}

public class IllegalStateException extends Exception {
    public IllegalStateException(String message) {
        super(message);
    }
}
